package xyz.altaf.kioku.sync

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

/**
 * The canonical bytes of a record key are the record's storage identity on
 * the server and in local bookkeeping, so the Kotlin and Go encodings must
 * agree byte for byte. The expected values are generated by the kioku-sync
 * server from the same proto; if this test fails after a protocol change,
 * regenerate both sides together.
 */
class RecordKeysTest {

    private val mangaSource = 7L
    private val mangaUrl = "https://example.com/manga"

    private fun hex(bytes: ByteArray) = bytes.joinToString("") { "%02x".format(it) }

    @Test
    fun `keys encode identically to the server`() {
        val goldens = mapOf(
            "manga" to "0a1d0807121968747470733a2f2f6578616d706c652e636f6d2f6d616e6761",
            "chapter" to "12230a1d0807121968747470733a2f2f6578616d706c652e636f6d2f6d616e676112026331",
            "history" to "4a230a1d0807121968747470733a2f2f6578616d706c652e636f6d2f6d616e676112026331",
            "category" to "1a080a066361742d6964",
            "track" to "22210a1d0807121968747470733a2f2f6578616d706c652e636f6d2f6d616e67611003",
            "preference" to "2a08707265662d6b6579",
            "sourcePref" to "32110a09736f757263655f6964120470726566",
            "extStore" to "3a1568747470733a2f2f696e6465782e6578616d706c65",
            "sourceName" to "402a",
        )
        val keys = mapOf(
            "manga" to RecordKeys.manga(mangaSource, mangaUrl),
            "chapter" to RecordKeys.chapter(mangaSource, mangaUrl, "c1"),
            "history" to RecordKeys.history(mangaSource, mangaUrl, "c1"),
            "category" to RecordKeys.category("cat-id"),
            "track" to RecordKeys.track(mangaSource, mangaUrl, 3),
            "preference" to RecordKeys.preference("pref-key"),
            "sourcePref" to RecordKeys.sourcePreference("source_id", "pref"),
            "extStore" to RecordKeys.extensionStore("https://index.example"),
            "sourceName" to RecordKeys.sourceName(42),
        )
        for ((name, key) in keys) {
            assertEquals(
                goldens.getValue(name),
                hex(key.toByteArray()),
                "canonical bytes of $name drifted from the server",
            )
        }
    }

    @Test
    fun `distinct kinds never share canonical bytes`() {
        val keys = listOf(
            RecordKeys.chapter(1, "m", "c"),
            RecordKeys.history(1, "m", "c"),
            RecordKeys.preference("c"),
            RecordKeys.sourceName(1),
        ).map { hex(it.toByteArray()) }
        assertEquals(keys.size, keys.toSet().size)
    }
}
